def test_list_messages_pager(transport_name: str = "grpc"):
    client = ChatServiceClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.list_messages), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            message.ListMessagesResponse(
                messages=[
                    message.Message(),
                    message.Message(),
                    message.Message(),
                ],
                next_page_token="abc",
            ),
            message.ListMessagesResponse(
                messages=[],
                next_page_token="def",
            ),
            message.ListMessagesResponse(
                messages=[
                    message.Message(),
                ],
                next_page_token="ghi",
            ),
            message.ListMessagesResponse(
                messages=[
                    message.Message(),
                    message.Message(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_messages(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, message.Message) for i in results)


