def test_list_reactions_pager(transport_name: str = "grpc"):
    client = ChatServiceClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(type(client.transport.list_reactions), "__call__") as call:
        # Set the response to a series of pages.
        call.side_effect = (
            reaction.ListReactionsResponse(
                reactions=[
                    reaction.Reaction(),
                    reaction.Reaction(),
                    reaction.Reaction(),
                ],
                next_page_token="abc",
            ),
            reaction.ListReactionsResponse(
                reactions=[],
                next_page_token="def",
            ),
            reaction.ListReactionsResponse(
                reactions=[
                    reaction.Reaction(),
                ],
                next_page_token="ghi",
            ),
            reaction.ListReactionsResponse(
                reactions=[
                    reaction.Reaction(),
                    reaction.Reaction(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_reactions(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, reaction.Reaction) for i in results)


