def test_list_custom_emojis_pager(transport_name: str = "grpc"):
    client = ChatServiceClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_custom_emojis), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            reaction.ListCustomEmojisResponse(
                custom_emojis=[
                    reaction.CustomEmoji(),
                    reaction.CustomEmoji(),
                    reaction.CustomEmoji(),
                ],
                next_page_token="abc",
            ),
            reaction.ListCustomEmojisResponse(
                custom_emojis=[],
                next_page_token="def",
            ),
            reaction.ListCustomEmojisResponse(
                custom_emojis=[
                    reaction.CustomEmoji(),
                ],
                next_page_token="ghi",
            ),
            reaction.ListCustomEmojisResponse(
                custom_emojis=[
                    reaction.CustomEmoji(),
                    reaction.CustomEmoji(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        pager = client.list_custom_emojis(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, reaction.CustomEmoji) for i in results)


